import json
from lfx.custom.custom_component.component import Component
from lfx.io import MessageTextInput, Output
from lfx.schema.data import Data
from lfx.schema.message import Message


class MBGFlowBDetector(Component):
    display_name = "Flow B - Rule Based Detection"
    description = "Rule-based MBG signal detection. No LLM."
    icon = "shield-alert"
    name = "MBGFlowBDetector"

    inputs = [MessageTextInput(name="input_data", display_name="MBG Data JSON", required=True)]
    outputs = [
        Output(display_name="Detection Result", name="result", method="make_result"),
        Output(display_name="Structured Data", name="structured", method="make_data"),
        Output(display_name="JSON Result (for Flow C)", name="json_result", method="make_json_result"),
    ]

    SEVERITIES = ("rendah", "sedang", "tinggi")

    def _parse(self):
        raw = getattr(self.input_data, "text", self.input_data)
        data = json.loads(str(raw).strip())
        if not isinstance(data, dict):
            raise ValueError("Input harus berupa objek JSON.")
        if "error" in data and "schools" not in data:
            raise ValueError(f"Langkah sebelumnya gagal: {data['error']}")
        # Gagal keras kalau skema salah, supaya data yang salah bentuk tidak diam-diam jadi HIJAU.
        for key in ("schools", "operational_records", "student_reviews"):
            if not isinstance(data.get(key), list):
                raise ValueError(f'Field "{key}" wajib ada dan berupa daftar (boleh kosong).')
        return data

    def _valid_review(self, r):
        """Review valid = objek dengan severity rendah/sedang/tinggi dan needs_review boolean."""
        return (
            isinstance(r, dict)
            and str(r.get("severity", "")).strip().lower() in self.SEVERITIES
            and isinstance(r.get("needs_review"), bool)
        )

    def _detect(self):
        data = self._parse()
        schools = data.get("schools", [])
        ops = data.get("operational_records", [])
        reviews = data.get("student_reviews", [])
        results = []
        warnings = []

        known_ids = {s.get("school_id") for s in schools if isinstance(s, dict)}
        orphans = [r for r in reviews if not isinstance(r, dict) or r.get("school_id") not in known_ids]
        if orphans:
            warnings.append(f"{len(orphans)} ulasan memakai school_id yang tidak ada di daftar sekolah (tidak dihitung)")

        for school in schools:
            sid = school.get("school_id")
            name = school.get("school_name", sid)
            sr = [r for r in reviews if isinstance(r, dict) and r.get("school_id") == sid]
            so = [o for o in ops if o.get("school_id") == sid]

            # review yang bentuknya salah tidak dihitung diam-diam: dilaporkan sebagai peringatan
            bad = [r for r in sr if not self._valid_review(r)]
            good = [dict(r, severity=str(r["severity"]).strip().lower()) for r in sr if self._valid_review(r)]

            # hitung review yang ditandai perlu ditinjau ATAU severity tinggi
            # (severity tinggi selalu dihitung, walau needs_review lupa diisi)
            relevant = [r for r in good if r["needs_review"] or r["severity"] == "tinggi"]

            severity_counts = {"tinggi": 0, "sedang": 0, "rendah": 0}
            for r in relevant:
                severity_counts[r["severity"]] += 1

            # --- Aturan status ---
            # 1 sinyal severity TINGGI = langsung merah, tidak perlu menunggu pola berulang.
            has_critical = severity_counts["tinggi"] >= 1

            groups = {}
            for r in relevant:
                key = (r.get("menu") or "(menu tidak disebutkan)", r.get("category") or "lainnya")
                groups[key] = groups.get(key, 0) + 1

            red_pattern_reasons = []
            yellow_reasons = []
            for (menu, category), count in groups.items():
                if count >= 3:
                    red_pattern_reasons.append(f"{count} keluhan serupa untuk {menu} ({category})")
                elif count >= 1:
                    yellow_reasons.append(f"{count} keluhan perlu ditinjau untuk {menu} ({category})")

            missing = [o for o in so if not o.get("temperature_c") or not o.get("serving_time")]
            late = [o for o in so if o.get("distribution_status") == "late"]
            if bad:
                yellow_reasons.append(f"{len(bad)} ulasan tidak sesuai skema dan tidak dihitung (periksa data)")
            if missing:
                yellow_reasons.append(f"{len(missing)} catatan operasional belum lengkap")
            if late:
                yellow_reasons.append(f"{len(late)} pengiriman terlambat")

            # highlight: sinyal tunggal paling parah untuk ditonjolkan di ringkasan
            highlight = None
            if relevant:
                worst = max(relevant, key=lambda r: {"tinggi": 2, "sedang": 1, "rendah": 0}[r["severity"]])
                highlight = (
                    f"keluhan {worst.get('severity')} pada {worst.get('menu') or '(menu tidak disebutkan)'} "
                    f"({worst.get('category')})"
                )

            evidence = []
            if has_critical:
                evidence.append(
                    f"{severity_counts['tinggi']} keluhan severity TINGGI terdeteksi "
                    "(butuh perhatian segera, tidak menunggu pola berulang)"
                )
            evidence.extend(red_pattern_reasons)
            evidence.extend(yellow_reasons)

            if has_critical or red_pattern_reasons:
                status = "red"
            elif yellow_reasons:
                status = "yellow"
            else:
                status = "green"
                evidence.append("Tidak ada sinyal yang memenuhi aturan peringatan")

            last_updates = [x.get("last_updated") for x in so if x.get("last_updated")]
            last_updated = max(last_updates) if last_updates else "(belum ada)"

            results.append({
                "school_id": sid,
                "school_name": name,
                "status": status,
                "severity_counts": severity_counts,
                "highlight": highlight,
                "evidence": evidence,
                "last_updated": last_updated,
            })
        return results, warnings

    def _payload(self):
        results, warnings = self._detect()
        return {"schools": results, "warnings": warnings}

    def make_data(self) -> Data:
        try:
            return Data(data=self._payload())
        except Exception as e:
            self.status = f"Error: {e}"
            return Data(data={"error": str(e)})

    def make_json_result(self) -> Message:
        try:
            text = json.dumps(self._payload(), ensure_ascii=False, indent=2)
            self.status = text
            return Message(text=text)
        except Exception as e:
            self.status = f"Error: {e}"
            return Message(text=json.dumps({"error": str(e)}))

    def make_result(self) -> Message:
        try:
            results, warnings = self._detect()
            lines = ["MBG Guard - Flow B Detection", ""]
            for w in warnings:
                lines.append(f"PERINGATAN DATA: {w}")
            if warnings:
                lines.append("")
            for r in results:
                sc = r["severity_counts"]
                lines.append(f"{r['school_name']} — {r['status'].upper()}  "
                              f"(tinggi:{sc['tinggi']} sedang:{sc['sedang']} rendah:{sc['rendah']})")
                if r["highlight"]:
                    lines.append(f"- Sorotan: {r['highlight']}")
                for e in r["evidence"]:
                    lines.append(f"- Evidence: {e}")
                lines.append("")
            text = "\n".join(lines).strip()
            self.status = text
            return Message(text=text)
        except Exception as e:
            self.status = f"Error: {e}"
            return Message(text=f"Flow B error: {e}")
